// Общие шаги для дашборда (#b6cecf04). Только просмотр, ничего не меняют.
import { expect, Page } from '@playwright/test';

export type Lang = 'en' | 'he';

/** Удалённый блок (#b6cecf04) — ни одной из этих строк на дашборде быть не должно. */
export const REMOVED_BLOCK_TEXTS = ['A clear view of your day', 'All in one place', 'Open schedule'];

/** Заголовок блока графика, который теперь идёт сразу после карточки приветствия. */
export const SALES_JOBS_TITLE: Record<Lang, string> = { en: 'Sales & Jobs', he: 'מכירות ועבודות' };

/** Язык интерфейса: localStorage 'preferred-language' до загрузки страницы. */
export async function setLanguage(page: Page, lang: Lang) {
  await page.addInitScript((l) => {
    try { window.localStorage.setItem('preferred-language', l); } catch { /* ignore */ }
  }, lang);
}

export const greetingCard = (page: Page) => page.locator('section.tec-persona');

/** Открыть /dashboard и дождаться карточки приветствия и блока графика (иначе проверки «нет текста» бессмысленны). */
export async function openDashboard(page: Page, lang: Lang) {
  await setLanguage(page, lang);
  await page.goto('/dashboard');
  await expect(greetingCard(page)).toBeVisible();
  await expect(page.locator('main').getByText(SALES_JOBS_TITLE[lang], { exact: true }).first()).toBeVisible();
}

/** Т1: текста удалённого блока нет, и внутри main нет ссылок на /schedule. */
export async function expectClearViewBlockRemoved(page: Page) {
  const body = page.locator('body');
  for (const text of REMOVED_BLOCK_TEXTS) {
    await expect(body, `на дашборде не должно быть «${text}»`).not.toContainText(text);
  }
  await expect(
    page.locator('main a[href="/schedule"], main a[href^="/schedule?"], main a[href^="/schedule/"]'),
    'внутри main нет ссылок на расписание',
  ).toHaveCount(0);
}

/** П1: сразу за карточкой приветствия (следующий соседний элемент) — блок графика Sales & Jobs. */
export async function expectSalesJobsRightAfterGreeting(page: Page, lang: Lang) {
  await expect(page.locator('section.tec-persona + *')).toContainText(SALES_JOBS_TITLE[lang]);
}
